/**
 * TTOken Code sidebar rail: its icon buttons, the panels at the rail's foot,
 * the Issues request to the on-screen Session, and the Device button that
 * opens the Android device page in the right sidebar.
 * Generated by ttoken/apply-brand.mjs from ttoken/client/sidebar/ttoken-nav.tsx; edit it there.
 */
import { useCallback, useEffect, useState, useSyncExternalStore, type ReactNode } from 'react'
import clsx from 'clsx'
import type { Context as ClientContext } from '@deepseek-ai/cordis'
import { createSnapshotStore, type ObservableSnapshot } from '@deepseek-ai/dsh-client-store'
import { Tooltip } from '@deepseek-ai/dsh-client-ui-primitives'
import css from './SidebarRoot.module.css'

/** Panels listed at the rail's foot instead of its navigation. */
export const TTOKEN_FOOT_PANELS: readonly string[] = ['plugins', 'schedules']

/** Code review panel of the change-request bundle, which also registers the Issues View. */
export const TTOKEN_REVIEW_PANEL = 'forge-review'

/** Conversation View id of the chat transcript. */
export const TTOKEN_CHAT_VIEW = 'chat'

/** Conversation View id of the GitHub issue board. */
export const TTOKEN_ISSUES_VIEW = 'ttoken-issues'

/** Window event asking the on-screen Session header to select a View; `detail` is the View id. */
const SELECT_VIEW_EVENT = 'ttoken-code:select-view'

/** Window event of the on-screen Session header; `detail` is the shown View id, or undefined once the header unmounts. */
const VIEW_SHOWN_EVENT = 'ttoken-code:view-shown'

/** Window event asking the on-screen Session header to announce its shown View again. */
const VIEW_QUERY_EVENT = 'ttoken-code:view-query'

/**
 * View request made while no Session header was mounted to receive it. A global
 * panel unmounts the Conversation, so the request is repeated once when the next
 * header announces a different View, then dropped.
 */
let pendingView: string | undefined

/**
 * Ask the on-screen Session to show one of its Conversation Views.
 * @param view - Conversation View id; a Session without that View keeps its current one.
 */
export function requestConversationView(view: string): void {
  pendingView = view
  window.dispatchEvent(new CustomEvent(SELECT_VIEW_EVENT, { detail: view }))
}

/**
 * Follow the View the on-screen Session header shows, and deliver a pending
 * View request to a header that mounted after it was made.
 * @returns the shown View id, or undefined while no Session header is mounted.
 */
export function useShownConversationView(): string | undefined {
  const [shown, setShown] = useState<string | undefined>(undefined)
  useEffect(() => {
    const follow = (event: Event): void => {
      if (!(event instanceof CustomEvent)) return
      const view: unknown = event.detail
      setShown(typeof view === 'string' ? view : undefined)
      if (typeof view !== 'string' || pendingView === undefined) return
      const requested = pendingView
      pendingView = undefined
      if (requested !== view) window.dispatchEvent(new CustomEvent(SELECT_VIEW_EVENT, { detail: requested }))
    }
    window.addEventListener(VIEW_SHOWN_EVENT, follow)
    window.dispatchEvent(new CustomEvent(VIEW_QUERY_EVENT))
    return () => { window.removeEventListener(VIEW_SHOWN_EVENT, follow) }
  }, [])
  return shown
}

/** Right-sidebar page type of the Android device panel. */
const DEVICE_TAB_KIND = 'android-device'

/** The registered right-sidebar page types, read without importing the right sidebar package. */
interface RightTabTypes {
  entries(): readonly { readonly kind: string }[]
  subscribe(listener: () => void): () => void
}

/** The right sidebar's page opener, read without importing the right sidebar package. */
interface RightSidebar {
  openTab(kind: string): void
}

/**
 * Check the page-type registry another plugin provides under `sidebarRightTabs`.
 * @param value - the provided service.
 * @returns whether it lists and reports page types.
 */
function isRightTabTypes(value: unknown): value is RightTabTypes {
  return typeof value === 'object' && value !== null && 'entries' in value && typeof value.entries === 'function'
    && 'subscribe' in value && typeof value.subscribe === 'function'
}

/**
 * Check the right sidebar service another plugin provides under `sidebarRight`.
 * @param value - the provided service.
 * @returns whether it opens pages by kind.
 */
function isRightSidebar(value: unknown): value is RightSidebar {
  return typeof value === 'object' && value !== null && 'openTab' in value && typeof value.openTab === 'function'
}

/** Availability and opener of the Device button. */
export interface DeviceNav {
  /** Whether the Android device page type is registered. */
  readonly available: ObservableSnapshot<boolean>
  /** Open the Android device page in the right sidebar of the on-screen Session. */
  readonly open: () => void
}

/**
 * Follow the right sidebar's page types for the Device button.
 * @param ctx - Client root context of the sidebar plugin.
 * @returns availability that follows the page-type registry, and the opener.
 */
export function createDeviceNav(ctx: ClientContext): DeviceNav {
  const store = createSnapshotStore<boolean>(false)
  ctx.inject(['sidebarRightTabs'], (scope) => {
    const tabs: unknown = scope.get('sidebarRightTabs')
    if (!isRightTabTypes(tabs)) throw new Error('ui-sidebar: sidebarRightTabs does not list page types')
    const sync = (): void => { store.set(tabs.entries().some(entry => entry.kind === DEVICE_TAB_KIND)) }
    scope.effect(() => tabs.subscribe(sync), 'ui-sidebar: device page type')
    scope.effect(() => () => { store.set(false) }, 'ui-sidebar: device page type reset')
    sync()
  })
  return {
    available: { getSnapshot: () => store.getSnapshot(), subscribe: listener => store.subscribe(listener) },
    open: () => {
      const sidebarRight: unknown = ctx.get('sidebarRight')
      if (isRightSidebar(sidebarRight)) sidebarRight.openTab(DEVICE_TAB_KIND)
    },
  }
}

/**
 * Read whether the Device button shows.
 * @param deviceNav - Availability source; absent means the button never shows.
 * @returns whether the Android device page type is registered.
 */
export function useDeviceAvailable(deviceNav: ObservableSnapshot<boolean> | undefined): boolean {
  const subscribe = useCallback((listener: () => void) => deviceNav?.subscribe(listener) ?? (() => {}), [deviceNav])
  const getSnapshot = useCallback(() => deviceNav?.getSnapshot() ?? false, [deviceNav])
  return useSyncExternalStore(subscribe, getSnapshot)
}

/**
 * One icon button of the rail, drawn with the panel rows' 36px tile.
 * @param props.label - Localized label, used as the tooltip and accessible name.
 * @param props.icon - 18px glyph.
 * @param props.active - Whether the button shows the current view.
 * @param props.onPress - Action of the button.
 * @returns the button element.
 */
export function TtokenRailButton({ label, icon, active = false, onPress }: {
  label: string
  icon: ReactNode
  active?: boolean
  onPress: () => void
}) {
  return (
    <div className={clsx(css.panelEntry, active && css.panelEntryActive)}>
      <Tooltip label={label} delayMs={500} side="right">
        <button type="button" className={css.panelRow} aria-label={label} aria-current={active ? 'page' : undefined} onClick={onPress}>
          <span className={css.panelGlyph} aria-hidden="true">{icon}</span>
        </button>
      </Tooltip>
    </div>
  )
}

/** Outline glyph shared by the rail's own buttons. */
function RailGlyph({ children }: { children: ReactNode }) {
  return (
    <svg width={18} height={18} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6"
      strokeLinecap="round" strokeLinejoin="round">
      {children}
    </svg>
  )
}

/**
 * Glyph of the rail's Home button.
 * @returns the 18px outline glyph.
 */
export function TtokenHomeIcon() {
  return <RailGlyph><path d="M4 11.5 12 5l8 6.5V19a1 1 0 0 1-1 1h-4.5v-5h-5v5H5a1 1 0 0 1-1-1z" /></RailGlyph>
}

/**
 * Glyph of the rail's Issues button.
 * @returns the 18px outline glyph.
 */
export function TtokenIssuesIcon() {
  return <RailGlyph><circle cx="12" cy="12" r="8.5" /><circle cx="12" cy="12" r="1.6" fill="currentColor" /></RailGlyph>
}

/**
 * Glyph of the rail's Device button.
 * @returns the 18px outline glyph.
 */
export function TtokenDeviceIcon() {
  return <RailGlyph><rect x="6.5" y="3" width="11" height="18" rx="2.5" /><path d="M11 17.5h2" /></RailGlyph>
}
